// Provenance: agent-generated (Phase 1.5 Pillar A compliance)
// rvtest_config.h — Configuration header for s2s_rv32i_core
// Defines UDB_* macros that the riscv-arch-test v3 framework expects.
// Hand-crafted to match the core's capabilities (normally generated by udb-gen).

#ifndef RVTEST_CONFIG_H
#define RVTEST_CONFIG_H

// Core is RV32I, machine-mode only
#define UDB_MXLEN 32

// Extensions supported
#define I_SUPPORTED
#define ZICSR_SUPPORTED
#define ZIFENCEI_SUPPORTED

// Machine-mode support
#define STANDARD_SM_SUPPORTED
#define SM1P12P0_SUPPORTED

// No PMP
#define UDB_NUM_PMP_ENTRIES 0
#define UDB_NUM_USABLE_PMP_ENTRIES 0

// mtvec configuration
#define UDB_MTVEC_BASE_ALIGNMENT_DIRECT 4
#define UDB_MTVEC_BASE_ALIGNMENT_VECTORED 4
#define UDB_MTVEC_MODES_0

// mcountinhibit
#define UDB_MCOUNTINHIBIT_IMPLEMENTED

// mtval reports
#define UDB_REPORT_ENCODING_IN_MTVAL_ON_ILLEGAL_INSTRUCTION

// No time CSR (we emulate it from mtime if needed, but core has no mtime)
// Defining this avoids the emulation code that needs RVMODEL_MTIME_ADDRESS
// #define UDB_TIME_CSR_IMPLEMENTED

// Trap behavior
#define UDB_TRAP_ON_ECALL_FROM_M
#define UDB_TRAP_ON_EBREAK

// Misaligned load/store raises exception
// #define UDB_MISALIGNED_LDST  -- not defined = exceptions on misaligned

#endif // RVTEST_CONFIG_H
